function buildA2Lesson(slug: string): LessonData {
  const lessonDef = A2_LESSONS[slug as keyof typeof A2_LESSONS];
  if (!lessonDef) {
    throw new Error(`A2 lesson ${slug} not found`);
  }

  const slughyphen = slug.split("-");
  const order = parseInt(slughyphen[2]) || 1;

  const grammarSection: GrammarItem[] = [
    {
      title: "Present Tense & Accustomed Actions",
      spainContent: `Use present tense for habitual actions and current states. Example: "Cada día me despierto a las 7 y me levanto inmediatamente." Reflexive verbs are key at A2.`,
      latamContent: `Mexican Spanish uses the same present tense structure. Example: "Todos los días me levanto temprano." Focus on verb conjugation consistency.`,
      note: "Reflexive verbs (levantarse, vestirse, etc.) are crucial for describing daily routines.",
    },
    {
      title: `${lessonDef.title} Grammar Patterns`,
      spainContent: `Key verb patterns and sentence structures for this lesson in Peninsular Spanish, with appropriate regional expressions.`,
      latamContent: `Same grammar patterns with Mexican regional vocabulary and expressions that sound natural in everyday speech.`,
      note: "Both regions share core grammar; vocabulary variations are the key difference.",
    },
  ];

  const dialogues: DialogueScenario[] = [];

  // Spain dialogues
  for (let i = 0; i < 3; i++) {
    dialogues.push({
      id: `dialogue-spain-${i + 1}`,
      title: `${lessonDef.title} - Scene ${i + 1} (Spain)`,
      region: "SPAIN",
      setting: `Madrid/Barcelona setting for ${lessonDef.title}`,
      lines: [
        { speaker: "Ana", text: lessonDef.vocabulary[i]?.exampleSentenceSpain || `¿Qué tal? (Spain ${i + 1})`, region: "SPAIN", setting: `Madrid/Barcelona setting for ${lessonDef.title}` },
        { speaker: "Carlos", text: lessonDef.vocabulary[(i + 1) % lessonDef.vocabulary.length]?.exampleSentenceSpain || `Bien, gracias. (Spain ${i + 1})`, region: "SPAIN", setting: `Madrid/Barcelona setting for ${lessonDef.title}` },
        { speaker: "Ana", text: `¿Y tú? (Spain ${i + 1})`, region: "SPAIN", setting: `Madrid/Barcelona setting for ${lessonDef.title}` },
      ],
    });
  }

  // Mexico dialogues
  for (let i = 0; i < 3; i++) {
    dialogues.push({
      id: `dialogue-latam-${i + 1}`,
      title: `${lessonDef.title} - Scene ${i + 1} (Mexico)`,
      region: "LATAM",
      setting: `Mexico City/Guadalajara setting for ${lessonDef.title}`,
      lines: [
        { speaker: "María", text: lessonDef.vocabulary[i]?.exampleSentenceLatam || `¿Qué onda? (Mexico ${i + 1})`, region: "LATAM", setting: `Mexico City/Guadalajara setting for ${lessonDef.title}` },
        { speaker: "Diego", text: lessonDef.vocabulary[(i + 1) % lessonDef.vocabulary.length]?.exampleSentenceLatam || `Bien, ¿y tú? (Mexico ${i + 1})`, region: "LATAM", setting: `Mexico City/Guadalajara setting for ${lessonDef.title}` },
        { speaker: "María", text: `Órale, qué bueno. (Mexico ${i + 1})`, region: "LATAM", setting: `Mexico City/Guadalajara setting for ${lessonDef.title}` },
      ],
    });
  }

  const quiz: QuizQuestion[] = [
    {
      questionId: "q1",
      type: "multiple-choice",
      questionText: `Which Mexican greeting is the most casual?`,
      options: ["¿Cómo estás?", "¿Qué onda?", "Buenas días", "¿Qué tal?"],
      correctAnswer: "¿Qué onda?",
      explanation: "¿Qué onda? is the most casual, friendly Mexican greeting often used among friends. It means 'What's up?'",
    },
    {
      questionId: "q2",
      type: "multiple-choice",
      questionText: `In Mexico, which word is commonly used instead of "habitación"?`,
      options: ["Cuarto", "Pieza", "Espacio", "Lugar"],
      correctAnswer: "Cuarto",
      explanation: "In Mexico, 'cuarto' is the common word for room, whereas Spain uses 'habitación.'",
    },
    {
      questionId: "q3",
      type: "multiple-choice",
      questionText: `What does "ni modo" mean in Mexican Spanish?`,
      options: ["Never again", "No way", "Oh well, that's just how it is", "I'm joking"],
      correctAnswer: "Oh well, that's just how it is",
      explanation: "'Ni modo' is a classic Mexican expression meaning 'Oh well, that's just how it is' or 'No big deal.'",
    },
    {
      questionId: "q4",
      type: "multiple-choice",
      questionText: `How would you say "You're right" in Mexican Spanish?`,
      options: ["Tienes razón", "Estás correcto", "Te entiendo", "Sí, claro"],
      correctAnswer: "Tienes razón",
      explanation: "'Tienes razón' is the natural way to say 'You're right' in both Spain and Mexico.",
    },
    {
      questionId: "q5",
      type: "multiple-choice",
      questionText: `In Mexico, what is the casual way to say "No big deal"?`,
      options: ["Sin problema", "Tranquilo", "No importa", "All of the above"],
      correctAnswer: "All of the above",
      explanation: "All three expressions ('Sin problema', 'Tranquilo', 'No importa') are used in Mexico to say 'No big deal.'",
    },
  ];

  const flashcards: FlashcardItem[] = lessonDef.vocabulary.map((v, idx) => ({
    id: `fc-${slug}-${idx + 1}`,
    frontSpain: v.spainVariant,
    frontLatam: v.latamVariant,
    backEnglish: v.english,
    variantDifferenceNote: v.spainVariant !== v.latamVariant ? `Spain: "${v.spainVariant}", Mexico: "${v.latamVariant}"` : "Same in both regions",
    exampleSentenceSpain: v.exampleSentenceSpain || "",
    exampleSentenceLatam: v.exampleSentenceLatam || "",
    partOfSpeech: v.partOfSpeech,
  }));

  return {
    id: `lesson-${slug}`,
    slug,
    title: lessonDef.title,
    description: lessonDef.description,
    level: "A2",
    difficulty: "ELEMENTARY",
    order,
    imageUrl: null,
    durationMinutes: 20,
    isPublished: true,
    vocabularyTable: lessonDef.vocabulary,
    grammarSection,
    dialogues,
    quiz,
    flashcards,
    vocabularyJson: lessonDef.vocabulary.map((v) => ({
      word: v.word,
      translation: `${v.spainVariant} / ${v.latamVariant}`,
      partOfSpeech: v.partOfSpeech,
      example: v.exampleSentenceLatam,
    })),
    grammarJson: grammarSection.map((g) => ({
      title: g.title,
      content: `${g.spainContent} | ${g.latamContent}`,
    })),
    content: `# ${lessonDef.title}\n\n${lessonDef.description}\n\nThis A2 lesson covers practical vocabulary for intermediate learners, grammar patterns, real-world dialogues, and interactive practice. Master the vocabulary, understand grammar distinctions, and practice with contextual dialogues and quizzes.`,
  };
}

export function generateA2Lessons(): LessonData[] {
  const a2Slugs = Object.keys(A2_LESSONS);
  return a2Slugs.map((slug) => buildA2Lesson(slug));
}